INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (366725, 15561, 'Mint', 'en', 'Mahua Moitra vs Bengal officials: TMC MP moves privilege notice over late-night circuit house eviction', 'https://www.livemint.com/news/india/mahua-moitra-vs-bengal-officials-tmc-mp-moves-privilege-notice-over-late-night-circuit-house-eviction-11787023555416.html', 'In her notice sent under Rule 222 of the Rules of Procedure and Conduct of Business in Lok Sabha, Moitra has sought action against Nadia District Magistrate Srikant Palli, Additional District Magistrate Nirpendra Singh, and Nazareth Deputy Collector Anamika Bera, news agency PTI said.', 'https://www.livemint.com/lm-img/img/2026/08/18/1600x900/logo/PTI08-12-2026-000076B-0_1787023595045_1787023608581_f5286cd1-a100-4ffd-907c-f24d90714671.jpg', '2026-08-18T03:42:08+00:00', '2026-08-18T03:59:02.508147'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
