INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (367016, 15561, 'The Economic Times', 'en', 'Mahua Moitra moves privilege notice', 'https://economictimes.indiatimes.com/news/politics-and-nation/tmc-mp-mahua-moitra-moves-privilege-notice-over-late-night-order-to-vacate-wb-circuit-house/articleshow/133310272.cms', 'New Delhi: Trinamool Congress MP Mahua Moitra moved a privilege notice before Lok Sabha Speaker Om Birla against three senior officials, alleging a serious breach of protocol and contemptuous conduct after she was asked to vacate a circuit house in West Bengal''s Krishnanagar late in the night on August 14.In her notice sent under Rule 222 of the Rules of Procedure and Conduct of Business in Lok Sabha, dated August 16, Moitra has sought action against Nadia District Magistrate Srikant Palli, Additional District Magistrate Nirpendra Singh, and Nazareth Deputy Collector Anamika Bera.Also read: TM', '', '2026-08-18T03:09:13+00:00', '2026-08-18T04:01:46.677352'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
