INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (369226, 15566, 'Aaj Tak', 'hi', 'फिलीपींस के स्कूल में छात्र ने बरसाईं गोलियां, खुद को भी मारी गोली', 'https://www.aajtak.in/world/story/philippines-school-firing-student-shooting-dead-gun-violence-zamboanga-ntc-mnrd-dskc-2624524-2026-08-18', 'फिलीपींस के ज़ाम्बोआंगा में Ateneo de Zamboanga University के हाई स्कूल में 9वीं कक्षा के एक छात्र ने कथित तौर पर क्लास के अंदर फायरिंग कर दी. हमले में एक छात्र की मौत हो गई, जिसके बाद आरोपी ने खुद को भी गोली मार ली. घटना में कुल दो लोगों की मौत हुई है. पुलिस अब हमले की वजह और हथियार स्कूल तक पहुंचने की जांच कर रही है.', '', '2026-08-18T06:10:10+00:00', '2026-08-18T06:40:08.122776'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
