INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (367435, 15567, 'The Hindu', 'en', 'Jharkhand protest LIVE: Govt. cancels JSSC-CGL exam; Devendra Nath Mahto ends hunger strike', 'https://www.thehindu.com/news/national/jharkhand/jharkhand-student-protest-live-updates-govt-cancels-jssc-cgl-exam-reforms-devendra-nath-mahto-august-18-2026/article71358897.ece', 'Ravindra Paswan, leader of the JPSC-JSSC Reform Manch, which has been leading the protest, said the agitation would continue as their key demand of a Central Bureau of Investigation (CBI) probe into alleged examination irregularities had not been met.', '', '2026-08-18T04:38:32+00:00', '2026-08-18T04:48:45.615357'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (367518, 15567, 'Aaj Tak', 'hi', 'हमसे सब छ‍िन जाएगा... JSSC-CGL रद्द होने पर रोने लगे पास अभ्यर्थी', 'https://www.aajtak.in/education/news/story/jharkhand-jssc-cgl-exam-cancellation-student-protest-cbi-investigation-edmm-dskc-2624486-2026-08-18', 'JSSC-CGL रद्द होने के बाद वो अभ्यर्थी सामने आ गए हैं जो पहले इस परीक्षा को पास कर चुके थे. उनका कहना है कि हम एक निष्पक्ष प्रक्रिया के जरिए शामिल हुए थे तो फिर ऐसा कदम क्यों उठाया जा रहा है? हमारा कहना है कि आप जांच करवाइए. जांच में जो गड़बड़ मिलेगा, उसे हटाइए न, हम लोग आपसे सहमत हैं.', '', '2026-08-18T04:26:47+00:00', '2026-08-18T04:49:46.677681'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (367526, 15567, 'Aaj Tak', 'hi', 'देवेंद्र महतो ने कहा कि सोनम सर से प्रेरणा लेकर लड़ी लड़ाई', 'https://www.aajtak.in/short-videos/video/jharkhand-exam-cancelled-jpsc-cgl-hemant-soren-tdpl-jharkhand-devendra-mahto-hunger-strike-break-mmtc-2624497-2026-08-18', 'रांची में JSSC-CGL और TDPL की सभी परीक्षाएं रद्द करने के सरकार के फैसले के बाद छात्र नेता देवेंद्र नाथ महतो ने सोनम वांगचुक से बातचीत की। उन्होंने कहा कि उनके मार्गदर्शन से छात्रों को आंदोलन की प्रेरणा मिली।', '', '2026-08-18T04:41:19+00:00', '2026-08-18T04:49:46.794946'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
