INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (369485, 15586, 'The Economic Times', 'en', 'Indian bonds wobble on oil strain, RBI swap pullback', 'https://economictimes.indiatimes.com/markets/bonds/indian-bonds-wobble-on-oil-strain-rbi-swap-pullback/articleshow/133313452.cms', 'On Tuesday morning, Indian government bonds faced a downturn as oil prices spiked beyond ninety dollars. Concerns escalated after the central bank prematurely ended a diaspora deposit scheme, leading to uncertainty in the market. This pullback in liquidity support has rendered bonds susceptible to changes in oil prices and international rates. The five-year note saw a significant yield rise recently.', 'https://img.etimg.com/photo/msid-133313452,imgsize-22206.cms', '2026-08-18T06:17:54+00:00', '2026-08-18T06:42:15.827088'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (370361, 15586, 'The Hindu BusinessLine', 'en', 'Cash still king in India despite digital boom, says RBI Deputy Governor Murmu', 'https://www.thehindubusinessline.com/money-and-banking/cash-still-king-in-india-despite-digital-boom-says-rbi-deputy-governor-murmu/article71359298.ece', 'Addressing central bankers from across the world, Murmu noted that currency in circulation continues to grow at double-digit rates despite a decline in cash’s share of individual transactions due to increasing digital payment adoption.', 'https://bl-i.thgim.com/public/incoming/pmvoa8/article71359303.ece/alternates/LANDSCAPE_1200/IMG_Photo_of_Sh_S_C_Murm_2_1_TGEVE59M.jpg', '2026-08-18T07:08:56+00:00', '2026-08-18T07:29:57.031008'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
