INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (372875, 15586, 'The Economic Times', 'en', 'RBI finds cash demand harder to predict', 'https://economictimes.indiatimes.com/news/economy/finance/rbi-finds-cash-demand-harder-to-predict-as-digital-payments-grow/articleshow/133317778.cms', 'Kolkata: The Reserve Bank of India is facing a challenge in predicting the future demand for currency notes as the currency in circulation has been growing at double-digit rates despite growing popularity of digital payments, deputy governor SC Murmu said."Currency in circulation continues to grow at double-digit rates even as cash''s share of individual transactions declines, thanks to growing digital payment adoption. That combination makes future demand harder to predict, which complicates our planning for production and distribution capacity," Murmu said at a meeting of central bankers held', '', '2026-08-18T09:34:08+00:00', '2026-08-18T10:07:04.800009'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
